package dev.rajeev.shortener.domain;

import dev.rajeev.shortener.analytics.AnalyticsQueue;
import dev.rajeev.shortener.analytics.ClickEvent;
import dev.rajeev.shortener.analytics.ClickNormalizer;
import dev.rajeev.shortener.repository.AliasTakenException;
import dev.rajeev.shortener.repository.LinkRepository;
import dev.rajeev.shortener.repository.LinkStats;
import java.time.Clock;
import java.util.Locale;

/**
 * Application service: owns the use cases, knows nothing about HTTP. Routes are a thin adapter
 * over this class, which is what makes behaviour testable without a server and what lets the
 * orchestrator's impact analysis point at one module when a rule changes.
 */
public class LinkService {

    public record CreateResult(Link link, boolean created) {}

    private final LinkRepository repo;
    private final CodeGenerator codegen;
    private final AnalyticsQueue analytics;
    private final UrlPolicy urlPolicy;
    private final Clock clock;

    public LinkService(LinkRepository repo, CodeGenerator codegen, AnalyticsQueue analytics, UrlPolicy urlPolicy, Clock clock) {
        this.repo = repo;
        this.codegen = codegen;
        this.analytics = analytics;
        this.urlPolicy = urlPolicy;
        this.clock = clock;
    }

    public CreateResult create(CreateLinkRequest req, String idempotencyKey) {
        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
            var existing = repo.findByIdempotencyKey(idempotencyKey);
            if (existing.isPresent()) return new CreateResult(existing.get(), false);
        }
        validate(req);
        validateExpiry(req);

        String normalized = switch (urlPolicy.evaluate(req.url())) {
            case UrlPolicy.Ok ok -> ok.normalized();
            case UrlPolicy.Rejected rejected -> throw new DomainException(rejected.code(), rejected.message());
        };

        String code;
        if (req.customAlias() != null) {
            if (LinkRules.RESERVED_CODES.contains(req.customAlias().toLowerCase(Locale.ROOT))) {
                throw new DomainException(ErrorCode.ALIAS_RESERVED, "'" + req.customAlias() + "' is reserved");
            }
            code = req.customAlias();
        } else {
            try {
                code = codegen.generate(repo::exists);
            } catch (CodeExhaustedException e) {
                throw new DomainException(ErrorCode.CODE_EXHAUSTED, e.getMessage());
            }
        }

        Link link = new Link(code, normalized, clock.instant(), null, req.expiresAt(), req.customAlias() != null, req.ownerId());
        try {
            repo.insert(link);
        } catch (AliasTakenException e) {
            throw new DomainException(ErrorCode.ALIAS_TAKEN, e.getMessage());
        }
        if (idempotencyKey != null && !idempotencyKey.isBlank()) repo.rememberIdempotencyKey(idempotencyKey, code, clock.instant());
        return new CreateResult(link, true);
    }

    /** Explicit validation so the rules hold for every caller, not only for @Valid at the HTTP edge. */
    private static void validate(CreateLinkRequest req) {
        if (req == null || req.url() == null || req.url().isBlank()) throw new DomainException(ErrorCode.VALIDATION, "url is required");
        if (req.url().length() > 8192) throw new DomainException(ErrorCode.VALIDATION, "url is too long");
        if (req.customAlias() != null && !LinkRules.CUSTOM_ALIAS_PATTERN.matcher(req.customAlias()).matches()) {
            throw new DomainException(ErrorCode.VALIDATION, "alias must be 4-32 URL-safe characters");
        }
        if (req.ownerId() != null && req.ownerId().length() > 128) throw new DomainException(ErrorCode.VALIDATION, "ownerId is too long");
    }

    private void validateExpiry(CreateLinkRequest req) {
        if (req.expiresAt() != null && !req.expiresAt().isAfter(clock.instant())) {
            throw new DomainException(ErrorCode.VALIDATION, "expiresAt must be in the future");
        }
    }

    /** Returns the active link or throws NOT_FOUND / GONE. */
    public Link resolve(String code) {
        Link link = repo.findByCode(code).orElseThrow(() -> new DomainException(ErrorCode.NOT_FOUND, "short link not found"));
        if (link.deleted()) throw new DomainException(ErrorCode.GONE, "short link has been deleted");
        // Expiry is evaluated on read against the injected clock: no background sweeper, no drift between workers.
        if (link.expiredAt(clock.instant())) throw new DomainException(ErrorCode.EXPIRED, "short link has expired");
        return link;
    }

    /** Resolve + fire-and-forget analytics. Redirect latency never waits on the store. */
    public Link resolveAndTrack(String code, String referrer, String userAgent) {
        Link link = resolve(code);
        analytics.enqueue(new ClickEvent(link.code(), clock.instant(), ClickNormalizer.referrer(referrer), ClickNormalizer.userAgent(userAgent)));
        return link;
    }

    public Link get(String code) {
        return resolve(code);
    }

    public void remove(String code) {
        Link link = repo.findByCode(code).orElseThrow(() -> new DomainException(ErrorCode.NOT_FOUND, "short link not found"));
        if (link.deleted()) throw new DomainException(ErrorCode.GONE, "short link has already been deleted");
        repo.softDelete(code, clock.instant());
    }

    public LinkStats stats(String code, int days, int topN) {
        repo.findByCode(code).orElseThrow(() -> new DomainException(ErrorCode.NOT_FOUND, "short link not found"));
        // Stats stay readable after deletion: owners often want the final numbers.
        analytics.flush();
        return repo.stats(code, days, topN);
    }
}

package dev.rajeev.shortener.web;

import dev.rajeev.shortener.domain.DomainException;
import dev.rajeev.shortener.domain.ErrorCode;
import jakarta.servlet.http.HttpServletRequest;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.HttpRequestMethodNotSupportedException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.method.annotation.HandlerMethodValidationException;
import org.springframework.web.servlet.resource.NoResourceFoundException;

/**
 * One place where domain outcomes become HTTP statuses. {@link #statusFor} is an exhaustive switch
 * over {@link ErrorCode}: adding a code without deciding its status does not compile.
 */
@RestControllerAdvice
public class ApiExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(ApiExceptionHandler.class);

    static HttpStatus statusFor(ErrorCode code) {
        return switch (code) {
            case VALIDATION, INVALID_URL -> HttpStatus.BAD_REQUEST;
            case URL_NOT_ALLOWED, ALIAS_RESERVED -> HttpStatus.UNPROCESSABLE_ENTITY;
            case ALIAS_TAKEN -> HttpStatus.CONFLICT;
            case NOT_FOUND -> HttpStatus.NOT_FOUND;
            case GONE, EXPIRED -> HttpStatus.GONE;
            case CODE_EXHAUSTED -> HttpStatus.SERVICE_UNAVAILABLE;
            case RATE_LIMITED -> HttpStatus.TOO_MANY_REQUESTS;
        };
    }

    @ExceptionHandler(DomainException.class)
    ResponseEntity<ApiError> domain(DomainException e, HttpServletRequest req) {
        return ResponseEntity.status(statusFor(e.code())).body(new ApiError(e.code().name(), e.getMessage(), RequestIdFilter.current(req)));
    }

    @ExceptionHandler({MethodArgumentNotValidException.class, HandlerMethodValidationException.class, HttpMessageNotReadableException.class})
    ResponseEntity<ApiError> validation(Exception e, HttpServletRequest req) {
        String message = e instanceof MethodArgumentNotValidException m && m.getBindingResult().getFieldError() != null
                ? m.getBindingResult().getFieldError().getField() + ": " + m.getBindingResult().getFieldError().getDefaultMessage()
                : "request body is malformed";
        return ResponseEntity.badRequest().body(new ApiError(ErrorCode.VALIDATION.name(), message, RequestIdFilter.current(req)));
    }

    @ExceptionHandler(NoResourceFoundException.class)
    ResponseEntity<ApiError> notFound(NoResourceFoundException e, HttpServletRequest req) {
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(new ApiError(ErrorCode.NOT_FOUND.name(), "no such resource", RequestIdFilter.current(req)));
    }

    @ExceptionHandler(HttpRequestMethodNotSupportedException.class)
    ResponseEntity<ApiError> method(HttpRequestMethodNotSupportedException e, HttpServletRequest req) {
        return ResponseEntity.status(HttpStatus.METHOD_NOT_ALLOWED).body(new ApiError("METHOD_NOT_ALLOWED", e.getMessage(), RequestIdFilter.current(req)));
    }

    @ExceptionHandler(Exception.class)
    ResponseEntity<ApiError> unhandled(Exception e, HttpServletRequest req) {
        log.error("unhandled error [requestId={}]", RequestIdFilter.current(req), e);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(new ApiError("INTERNAL", "internal error", RequestIdFilter.current(req)));
    }
}

package dev.rajeev.shortener.domain;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import dev.rajeev.shortener.analytics.AnalyticsQueue;
import dev.rajeev.shortener.repository.InMemoryLinkRepository;
import dev.rajeev.shortener.repository.LinkStats;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import java.util.ArrayDeque;
import java.util.Deque;
import java.util.List;
import java.util.function.Predicate;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;

class LinkServiceTest {

    /** Test clock that advances one second per read, so ordering is deterministic. */
    static class TickingClock extends Clock {
        private Instant now = Instant.now().minusSeconds(60);

        @Override public ZoneOffset getZone() { return ZoneOffset.UTC; }
        @Override public Clock withZone(java.time.ZoneId zone) { return this; }
        @Override public Instant instant() { now = now.plusSeconds(1); return now; }
    }

    static class QueuedCodes implements CodeGenerator {
        final Deque<String> codes = new ArrayDeque<>(List.of("gen0001", "gen0002", "gen0003"));

        @Override
        public String generate(Predicate<String> exists) {
            while (!codes.isEmpty()) {
                String c = codes.pop();
                if (!exists.test(c)) return c;
            }
            throw new IllegalStateException("out of test codes");
        }
    }

    private final InMemoryLinkRepository repo = new InMemoryLinkRepository();
    private final AnalyticsQueue analytics = new AnalyticsQueue(repo, 10_000, 10, 100, 3);
    private final LinkService service = new LinkService(repo, new QueuedCodes(), analytics, new UrlPolicy(2048, List.of("localhost:8080"), false), new TickingClock());

    @AfterEach
    void tearDown() {
        analytics.close();
    }

    private static ErrorCode codeOf(Runnable r) {
        DomainException e = assertThrows(DomainException.class, r::run);
        return e.code();
    }

    @Test
    void createsALinkWithAGeneratedCode() {
        var result = service.create(new CreateLinkRequest("https://example.com", null, null, null), null);
        assertTrue(result.created());
        assertEquals("gen0001", result.link().code());
        assertEquals("https://example.com/", result.link().targetUrl());
        assertFalse(result.link().custom());
        assertNull(result.link().deletedAt());
    }

    @Test
    void usesACustomAliasWhenGiven() {
        var result = service.create(new CreateLinkRequest("https://example.com", "my-link", "owner-1", null), null);
        assertEquals("my-link", result.link().code());
        assertTrue(result.link().custom());
        assertEquals("owner-1", result.link().ownerId());
    }

    @Test
    void rejectsTakenReservedAndInvalidAliases() {
        service.create(new CreateLinkRequest("https://example.com", "taken1", null, null), null);
        assertEquals(ErrorCode.ALIAS_TAKEN, codeOf(() -> service.create(new CreateLinkRequest("https://other.com", "taken1", null, null), null)));
        assertEquals(ErrorCode.ALIAS_RESERVED, codeOf(() -> service.create(new CreateLinkRequest("https://example.com", "health", null, null), null)));
        assertEquals(ErrorCode.VALIDATION, codeOf(() -> service.create(new CreateLinkRequest("https://example.com", "a b", null, null), null)));
        assertEquals(ErrorCode.VALIDATION, codeOf(() -> service.create(new CreateLinkRequest("", null, null, null), null)));
        assertEquals(ErrorCode.VALIDATION, codeOf(() -> service.create(new CreateLinkRequest("https://example.com", null, "x".repeat(200), null), null)));
    }

    @Test
    void rejectsDisallowedUrlsWithThePolicyReason() {
        assertEquals(ErrorCode.URL_NOT_ALLOWED, codeOf(() -> service.create(new CreateLinkRequest("javascript:alert(1)", null, null, null), null)));
        assertEquals(ErrorCode.INVALID_URL, codeOf(() -> service.create(new CreateLinkRequest("nope", null, null, null), null)));
        assertEquals(ErrorCode.URL_NOT_ALLOWED, codeOf(() -> service.create(new CreateLinkRequest("http://localhost:8080/x", null, null, null), null)));
    }

    @Test
    void isIdempotentOnIdempotencyKey() {
        var a = service.create(new CreateLinkRequest("https://example.com", null, null, null), "key-1");
        var b = service.create(new CreateLinkRequest("https://example.com", null, null, null), "key-1");
        assertTrue(a.created());
        assertFalse(b.created());
        assertEquals(a.link().code(), b.link().code());
    }

    @Test
    void mapsCodeExhaustionToCodeExhausted() {
        LinkService exhausted = new LinkService(repo, exists -> { throw new CodeExhaustedException(5); }, analytics, new UrlPolicy(2048, List.of(), false), Clock.systemUTC());
        assertEquals(ErrorCode.CODE_EXHAUSTED, codeOf(() -> exhausted.create(new CreateLinkRequest("https://example.com", null, null, null), null)));
    }

    @Test
    void storesExpiresAtAndExposesItOnTheLink() {
        Instant expires = Instant.now().plusSeconds(3600);
        Link link = service.create(new CreateLinkRequest("https://example.com", null, null, expires), null).link();
        assertEquals(expires, link.expiresAt());
        assertNull(service.create(new CreateLinkRequest("https://example.com", null, null, null), null).link().expiresAt());
    }

    @Test
    void rejectsAnExpiryInThePastAsValidation() {
        assertEquals(ErrorCode.VALIDATION, codeOf(() -> service.create(new CreateLinkRequest("https://example.com", null, null, Instant.now().minusSeconds(3600)), null)));
    }

    @Test
    void resolvesExpiredOnceTheInjectedClockPassesExpiresAtAndStatsStayReadable() {
        // The fake clock advances one second per read; expire 2.5 s from the current tick.
        Instant expires = Instant.now().minusSeconds(60).plusMillis(3500);
        Link link = service.create(new CreateLinkRequest("https://example.com", null, null, expires), null).link();
        service.resolveAndTrack(link.code(), null, null); // still valid
        assertEquals(ErrorCode.EXPIRED, codeOf(() -> service.resolve(link.code()))); // clock has moved past expiry
        assertEquals(1, service.stats(link.code(), 30, 5).totalClicks());
    }

    @Test
    void resolvesActiveLinksAndTracksClicksAsynchronously() {
        Link link = service.create(new CreateLinkRequest("https://example.com", null, null, null), null).link();
        Link resolved = service.resolveAndTrack(link.code(), "https://news.ycombinator.com/", "curl/8");
        assertEquals("https://example.com/", resolved.targetUrl());
        assertEquals(1, analytics.metrics().enqueued());
        LinkStats stats = service.stats(link.code(), 30, 5);
        assertEquals(1, stats.totalClicks());
        assertEquals(List.of(new LinkStats.ReferrerCount("news.ycombinator.com", 1)), stats.topReferrers());
        assertEquals(List.of(new LinkStats.UserAgentCount("curl", 1)), stats.topUserAgents());
    }

    @Test
    void returnsNotFoundForUnknownAndGoneForDeleted() {
        assertEquals(ErrorCode.NOT_FOUND, codeOf(() -> service.resolve("missing")));
        Link link = service.create(new CreateLinkRequest("https://example.com", null, null, null), null).link();
        service.remove(link.code());
        assertEquals(ErrorCode.GONE, codeOf(() -> service.resolve(link.code())));
        assertEquals(ErrorCode.GONE, codeOf(() -> service.remove(link.code())));
        assertEquals(ErrorCode.NOT_FOUND, codeOf(() -> service.remove("missing")));
    }

    @Test
    void keepsStatsReadableAfterDeletion() {
        Link link = service.create(new CreateLinkRequest("https://example.com", null, null, null), null).link();
        service.resolveAndTrack(link.code(), null, null);
        service.remove(link.code());
        assertEquals(1, service.stats(link.code(), 30, 5).totalClicks());
        assertEquals(ErrorCode.NOT_FOUND, codeOf(() -> service.stats("missing", 30, 5)));
    }
}
